-- Layercake.etl_daily_count_loaded (src/sql/Layercake/Tables/Layercake.etl_daily_count_loaded.sql)
IF OBJECT_ID(N'Layercake.etl_daily_count_loaded', N'U') IS NULL
BEGIN
    /*====================================================================
        Layercake.etl_daily_count_loaded
        Control layer - table, keys and intrinsic indexes
    ====================================================================*/

    -- PER-DATE LOAD TRACKING (02 v9). One row per calendar date whose daily count
    -- rows (detail AND main) committed successfully; written inside the chunk's own
    -- transaction, so the marker cannot exist without the data or vice versa.
    --   * work list         = spine dates <= today with NO row here
    --   * resume after fail = the dead run's chunk was never marked
    --   * history protection= a marked date is never touched again unless
    --                         @RebuildFrom / @FullRebuild clears its marker
    -- The current day is deliberately NEVER marked, so it is rebuilt every run.
    --
    -- NOTE: 02_usp_load_silver_v9.sql seeds this table on FIRST CREATION from the
    -- v8 high-water mark. On a blank database there is nothing to seed (silver is
    -- empty), so no seed is reproduced here - the first silver run correctly walks
    -- the whole spine as its historical backfill.
    create table Layercake.etl_daily_count_loaded
    (
        [date]     date not null constraint pk_etl_daily_count_loaded primary key clustered,
        loaded_at  datetime2(3) not null constraint df_etl_dcl_at default sysdatetime(),
        run_id     uniqueidentifier null,     -- the run that loaded it
        batch_from date null,                 -- the chunk it was loaded in
        batch_to   date null
    );
END;
GO
-- Layercake.etl_daily_count_pending_rebuild (src/sql/Layercake/Tables/Layercake.etl_daily_count_pending_rebuild.sql)
IF OBJECT_ID(N'Layercake.etl_daily_count_pending_rebuild', N'U') IS NULL
BEGIN
    /*====================================================================
        Layercake.etl_daily_count_pending_rebuild
        Control layer - table, keys and intrinsic indexes
    ====================================================================*/

    -- RETROSPECTIVE CHANGE LOG (02 v9). The daily run does not rebuild history, so
    -- a state-range / payment / profile change reaching back into already-loaded
    -- dates is recorded here instead. At most ONE OPEN row per source (filtered
    -- unique index), holding the EARLIEST affected date since it was last applied.
    --   select * from Layercake.etl_daily_count_pending_rebuild where applied_at is null;
    --   exec Layercake.usp_load_silver @RebuildFrom = '2025-10-01';
    create table Layercake.etl_daily_count_pending_rebuild
    (
        pending_id        int identity not null
            constraint pk_etl_dc_pending primary key,
        [source]          varchar(20)  not null,      -- state_ranges | payments | member_profile | enrol_exception
        affected_from     date         not null,      -- earliest ALREADY-LOADED date affected
        detection_count   int          not null constraint df_etl_dc_pending_cnt   default 1,
        first_detected_at datetime2(3) not null constraint df_etl_dc_pending_first default sysdatetime(),
        last_detected_at  datetime2(3) not null constraint df_etl_dc_pending_last  default sysdatetime(),
        last_run_id       uniqueidentifier null,
        detail            nvarchar(400) null,
        applied_at        datetime2(3) null           -- set when a rebuild covered it
    );

    -- at most one open (unapplied) row per source
    create unique nonclustered index ux_etl_dc_pending_open
        on Layercake.etl_daily_count_pending_rebuild ([source])
        where applied_at is null;
END;
GO
