-- Layercake.fact_annual_rate_base (src/sql/Layercake/Tables/Layercake.fact_annual_rate_base.sql)
IF OBJECT_ID(N'Layercake.fact_annual_rate_base', N'U') IS NULL
BEGIN
    /*====================================================================
        Layercake.fact_annual_rate_base
        Gold layer - table, keys and intrinsic indexes
    ====================================================================*/

    ----------------------------------------------------
    --  Layercake.fact_annual_rate_base
    --  Straight copy of silv_annual_rate_base - the single reporting-facing
    --  source for the Growth / Retention / Renewal / Readmission DAX
    --  measures. Power BI connects HERE, never to the silver table, so silver
    --  can evolve without moving the model.
    --
    --  id int identity is the clustered PRIMARY KEY, matching the other star
    --  facts. The 5-column segment key is still the business grain and is
    --  enforced + made seekable by ux_fact_annual_rate_base_segment - the
    --  gold load's diff-sync matches on exactly those columns. The identity
    --  id is inert to the load (never referenced, assigned on insert) but
    --  gives every row a stable single-column handle.
    ----------------------------------------------------
    create table Layercake.fact_annual_rate_base
    (
        id                   int identity not null constraint pk_fact_annual_rate_base primary key clustered,
        campaign_year        int not null,          -- -> dim_campaign_year
        grade_id             int not null,          -- -> dim_membership_grade
        membership_status_id int not null,          -- -> dim_membership_status
        country_id           int not null,          -- -> dim_country (region rolls up from here)
        gender_id            int not null,          -- -> dim_gender
        members_start        int not null,
        members_end          int not null,
        members_joined       int not null,
        members_readmitted   int not null,
        members_lapsed       int not null,
        members_renewed      int not null
    );

    create unique nonclustered index ux_fact_annual_rate_base_segment
        on Layercake.fact_annual_rate_base
        (campaign_year, grade_id, membership_status_id, country_id, gender_id);
END;
GO
-- Layercake.fact_daily_member_count_detail (src/sql/Layercake/Tables/Layercake.fact_daily_member_count_detail.sql)
IF OBJECT_ID(N'Layercake.fact_daily_member_count_detail', N'U') IS NULL
BEGIN
    /*====================================================================
        Layercake.fact_daily_member_count_detail
        Gold layer - table, keys and intrinsic indexes
    ====================================================================*/

    ----------------------------------------------------
    --  Layercake.fact_daily_member_count_detail  (star detail fact)
    --  Every key a dim surrogate; identity id kept as a NONCLUSTERED pk, and
    --  the natural star grain is the unique CLUSTERED index so the window
    --  diff/delete/insert works off a single date_id-leading b-tree.
    --
    --  PaidMembers vs PaidMembersEvent are two independent readings of the
    --  same question, carried side by side so a report can show either or
    --  compare them (see silv_daily_count_detail for the rules):
    --    PaidMembers      - payment-driven: a paid subs position for the
    --                       campaign year, dated on or before the day.
    --    PaidMembersEvent - event-driven: Join + Renewal + Readmission,
    --                       accumulated from each 1 October. Lapsing does
    --                       not deduct.
    --  JoinEvents / RenewalEvents / ReadmissionEvents are the daily flows
    --  PaidMembersEvent is built from - additive over any date range, and a
    --  running total of them reproduces PaidMembersEvent. LapseEvents is
    --  reported alongside rather than netted off: members who had paid this
    --  campaign year and then lapsed.
    ----------------------------------------------------
    create table Layercake.fact_daily_member_count_detail
    (
        id                   int identity not null
            constraint pk_fact_daily_member_count_detail primary key nonclustered,
        date_id              int not null,    -- -> dim_date
        country_id           int not null,    -- -> dim_country (region rolls up here)
        gender_id            int not null,    -- -> dim_gender
        membership_grade_id  int not null,    -- -> dim_membership_grade (0 = N/A - incl. daily lapse rows; lapse is event-only)
        membership_status_id int not null,    -- -> dim_membership_status (Practising/Retired; 0 = N/A - incl. daily lapse rows)
        ActiveMembers        int not null,
        PaidMembers          int not null,    -- payment-driven (original)
        PaidMembersEvent     int not null,    -- event-driven (stock)
        JoinEvents           int not null,    -- event-driven components (daily flow)
        RenewalEvents        int not null,
        ReadmissionEvents    int not null,
        LapseEvents          int not null    -- reported, not deducted from PaidMembersEvent
    );

    create unique clustered index cx_fact_daily_member_count_detail
        on Layercake.fact_daily_member_count_detail
        (date_id, country_id, gender_id, membership_grade_id, membership_status_id);
END;
GO
-- Layercake.fact_membership_events (src/sql/Layercake/Tables/Layercake.fact_membership_events.sql)
IF OBJECT_ID(N'Layercake.fact_membership_events', N'U') IS NULL
BEGIN
    /*====================================================================
        Layercake.fact_membership_events
        Gold layer - table, keys and intrinsic indexes
    ====================================================================*/

    /*====================================================================
        8. GOLD - facts
        ------------------------------------------------------------------
        NOTE: fact_daily_member_count (the old natural-key headline fact) is
        retired and is deliberately NOT in this baseline. The star detail
        fact fact_daily_member_count_detail covers everything it reported -
        the daily headline is SUM(detail), region rolls up from dim_country,
        grade from dim_membership_grade.
    ====================================================================*/

    create table Layercake.fact_membership_events
