-- Layercake.ref_enrolment_exception (src/sql/Layercake/Tables/Layercake.ref_enrolment_exception.sql)
IF OBJECT_ID(N'Layercake.ref_enrolment_exception', N'U') IS NULL
BEGIN
    /*====================================================================
        Layercake.ref_enrolment_exception
        Silver layer - table, keys and intrinsic indexes
    ====================================================================*/

    -- Gap-fill dates for contacts whose enrolment/election dates are missing from
    -- the enrolment source. MAINTAINED BY THE PIPELINE since 20260928_02:
    -- Layercake.usp_load_ref_enrolment_exception (silver module 8a) runs on every
    -- silver load, immediately before silv_member_base, and is the ONLY thing that
    -- writes here.
    --
    -- The lifecycle it implements, and why each half is the way it is:
    --   * CAPTURE IS INSERT-ONLY. A contact captured once keeps the derived
    --     history it was captured with, for ever. Nothing re-derives an existing
    --     row, so a run can never move a date a count has already been built on.
    --   * SUPERSESSION IS A FLAG, NOT A DELETE. When real qualifying rows appear
    --     for a captured contact the row is stamped superseded_at rather than
    --     removed - deleting would throw away the audit trail of what the counts
    --     were built on, and it would change nothing in the derivation, because
    --     silv_member_base coalesces these dates in PER DATE with the real row
    --     winning. A superseded row is already inert wherever real data covers it,
    --     and still fills the gap wherever it does not (a contact who gains a
    --     qualifying election but still has no enrolment row keeps the derived
    --     enrolment date). superseded_at is CLEARED if the contact stops
    --     qualifying again, exactly as silv_data_anomaly re-opens a resolved row.
    --   * A row is never hard-deleted by any process. To remove one, do it by
    --     hand - it is still a curated table.
    --
    -- Shape history:
    --   * 20260910_01 - the campaign-year audit columns were added when the
    --     capture driver moved from the CE contact grade/lapse flags to
    --     Subs.vwSubsMemberStatuses evaluated for EVERY campaign year (paid =
    --     paid position that year; active = paid that year or the year before),
    --     condensed to one row per contact. They record WHY a contact was
    --     captured and the span of membership the subs history shows.
    create table Layercake.ref_enrolment_exception
    (
        contact_no                 nvarchar(200) not null,
        contact_id                 uniqueidentifier not null,
        member_grade               nvarchar(350) null,     -- grade at capture time (context only)
        derived_enrolment_date     date null,              -- Enrolled gap-fill (also carried on Elected rows where a source row supplies it)
        derived_election_date      date null,              -- Elected gap-fill
        enrolment_date_source      varchar(60) null,       -- 'Enrolment row (non-qualifying)' | 'Contact CreatedOn'
        election_date_source       varchar(60) null,       -- 'Enrolment row (non-qualifying)' | 'Rics_ElectionDate' | 'Contact CreatedOn (no election date)'
        has_subs_history           bit not null,           -- any row in Subs.vwSubsMemberStatuses at capture time (always 1 since 20260910_01 - the driver IS that view; kept for the recon scripts)
        -- the condensed per-campaign-year status from the subs view at capture
        -- (all null / 0 = captured before 20260910_01)
        first_active_campaign_year int null,               -- earliest campaign year the contact was active
        last_active_campaign_year  int null,               -- latest campaign year the contact was active (capped at the current year)
        first_paid_campaign_year   int null,               -- earliest campaign year with a paid position
        last_paid_campaign_year    int null,               -- latest campaign year with a paid position
        active_campaign_years      int not null constraint df_ref_enr_exc_active_cys default 0,   -- how many campaign years active
        paid_campaign_years        int not null constraint df_ref_enr_exc_paid_cys   default 0,   -- how many campaign years paid
        is_active_current          bit not null constraint df_ref_enr_exc_active_cur default 0,   -- active in the campaign year current at capture
        is_paid_current            bit not null constraint df_ref_enr_exc_paid_cur   default 0,   -- paid in the campaign year current at capture
        source_enrolment_rows      int not null constraint df_ref_enr_exc_src_rows   default 0,   -- source enrolment rows seen for the contact (0 = no enrolment row at all)
        -- lifecycle (20260928_02)
        superseded_at              datetime2(3) null,      -- stamped when the contact gained a qualifying vw_enrolment_base row; cleared if it loses it again
        superseded_reason          varchar(60) null,       -- 'Qualifying enrolment row' | 'Qualifying election row' | 'Qualifying enrolment + election row'
        _captured_at               datetime2(3) not null constraint df_ref_enr_exc_captured default sysdatetime(),
        _capture_source            varchar(20) not null,   -- 'seed' | 'topup' | 'daily-load'. No default: the one writer always supplies it, so a hand-insert that forgets fails loudly
        _last_seen_at              datetime2(3) not null constraint df_ref_enr_exc_seen default sysdatetime(),   -- last run in which the contact still had NO qualifying row
        constraint pk_ref_enrolment_exception primary key clustered (contact_no),
        constraint ck_ref_enr_exc_cap_src check (_capture_source in ('seed', 'topup', 'daily-load')),
        -- a reason is meaningful only on a superseded row, and vice versa
        constraint ck_ref_enr_exc_superseded check ((superseded_at is null     and superseded_reason is null)
                                                or (superseded_at is not null and superseded_reason is not null)),
        -- a row must fill at least one of the two dates or it does nothing
        constraint ck_ref_enr_exc_has_date check (derived_enrolment_date is not null
                                               or derived_election_date  is not null)
    );
END;
GO
-- Layercake.silv_annual_rate_base (src/sql/Layercake/Tables/Layercake.silv_annual_rate_base.sql)
IF OBJECT_ID(N'Layercake.silv_annual_rate_base', N'U') IS NULL
BEGIN
    /*====================================================================
        Layercake.silv_annual_rate_base
        Silver layer - table, keys and intrinsic indexes
    ====================================================================*/

    ----------------------------------------------------
    --  Layercake.silv_annual_rate_base
    --  Segment-level annual counts feeding the DAX rate measures. One row per
    --  campaign year per non-zero segment combination. Grain: campaign_year x
    --  grade x membership_status x country x gender (region rolls up from
    --  country in the Power BI model, so it is NOT a separate key here).
    --
    --  members_start / members_end  - member-grade snapshots at the 30 Sep
    --                                 boundaries (prior / current campaign year)
    --  members_joined / _readmitted /
    --  _lapsed / _renewed           - event counts within the campaign year
    --                                 (members_renewed includes the In-Year
    --                                 Readmission renewal subtype)
    --
    --  [Open with Alex - Renewal Rate 'quoted population' denominator:
    --   members_start is the interim proxy.]
    --  [Open with Alex - Readmission Rate denominator: which lapsed cohort.]
    ----------------------------------------------------
    create table Layercake.silv_annual_rate_base
    (
        campaign_year        int not null,      -- -> ref_campaign_year_config
        grade_id             int not null,      -- -> silv_ref_membership_grade
        membership_status_id int not null,      -- -> silv_ref_membership_status
        country_id           int not null,      -- -> silv_ref_country (region rolls up from here)
        gender_id            int not null,      -- -> silv_ref_gender
        members_start        int not null,
        members_end          int not null,
        members_joined       int not null,
        members_readmitted   int not null,
        members_lapsed       int not null,
        members_renewed      int not null,
        constraint pk_silv_annual_rate_base primary key clustered
            (campaign_year, grade_id, membership_status_id, country_id, gender_id)
    );
END;
GO
-- Layercake.silv_daily_count (src/sql/Layercake/Tables/Layercake.silv_daily_count.sql)
IF OBJECT_ID(N'Layercake.silv_daily_count', N'U') IS NULL
BEGIN
    /*====================================================================
        Layercake.silv_daily_count
        Silver layer - table, keys and intrinsic indexes
    ====================================================================*/

    ----------------------------------------------------
    --  Layercake.silv_daily_count
    --  ([date], region, grade) is the natural grain and the clustered PK, so
    --  a date window can be deleted + re-inserted idempotently.
    --  Both paid measures and the event components are plain SUMs over
    --  silv_daily_count_detail - see that table's header for what they mean.
    ----------------------------------------------------
    create table Layercake.silv_daily_count
    (
        [date]                  date not null,
        campaign_year           int not null,
        campaign_quarter        char(2) not null,
        region                  varchar(12) not null,
        grade                   varchar(12) not null,   -- enrolment, election, lapse
        active_count            int not null,
        paid_count              int not null,           -- payment-driven (original)
        paid_count_event        int not null,           -- event-driven (stock)
        event_join_count        int not null,           -- event-driven components (daily flow)
        event_renewal_count     int not null,
        event_readmission_count int not null,
        event_lapse_count       int not null,           -- reported, not deducted
        constraint pk_silv_daily_count primary key clustered ([date], region, grade)
    );
END;
GO
-- Layercake.silv_daily_count_detail (src/sql/Layercake/Tables/Layercake.silv_daily_count_detail.sql)
IF OBJECT_ID(N'Layercake.silv_daily_count_detail', N'U') IS NULL
BEGIN
    /*====================================================================
        Layercake.silv_daily_count_detail
        Silver layer - table, keys and intrinsic indexes
    ====================================================================*/

    ----------------------------------------------------
    --  Layercake.silv_daily_count_detail
    --  The main daily count at the finer grain
    --  [date] x region x country x gender x grade x membership status.
    --  Feeds gold fact_daily_member_count_detail. silv_daily_count is derived
    --  from this table (SUM over country/gender/status), so the two always
    --  reconcile. Date-leading clustered PK keeps the per-chunk delete +
    --  re-insert cheap and idempotent.
    --
    --  TWO PAID MEASURES, side by side and deliberately not reconciled:
    --    paid_count       - PAYMENT-driven. A payment event for the campaign
    --                       year with an adjusted renewal date on or before
    --                       the day. The original measure, unchanged.
    --    paid_count_event - EVENT-driven. Built from silv_membership_events:
    --                       paid from the campaign year's earliest Join /
    --                       Renewal / Readmission, and counted for the rest
    --                       of that year. Resets each 1 October. Lapsing
    --                       does NOT deduct.
    --  event_join_count / _renewal_ / _readmission_ are the daily FLOWS
    --  behind paid_count_event - a running total of them from the campaign
    --  year start reproduces it exactly at the day level.
    --  event_lapse_count is reported ALONGSIDE, not netted off: the
    --  contacts who had paid in this campaign year and then lapsed that day.
    ----------------------------------------------------
    create table Layercake.silv_daily_count_detail
    (
        [date]                  date not null,
        campaign_year           int not null,
        campaign_quarter        char(2) not null,
        region                  varchar(12) not null,   -- RANGE region (same as silv_daily_count)
        country_id              int not null,           -- -> silv_ref_country (contact's CURRENT country)
        gender_id               int not null,           -- -> silv_ref_gender
        grade                   varchar(12) not null,   -- enrolment, election, lapse
        membership_status_id    int not null,           -- -> silv_ref_membership_status (0 = N/A outside 'election')
        active_count            int not null,
        paid_count              int not null,           -- payment-driven (original)
        paid_count_event        int not null,           -- event-driven (stock)
        event_join_count        int not null,           -- event-driven components (daily flow)
        event_renewal_count     int not null,
        event_readmission_count int not null,
        event_lapse_count       int not null,           -- reported, not deducted - see the module header
        constraint pk_silv_daily_count_detail primary key clustered
            ([date], region, country_id, gender_id, grade, membership_status_id)
    );
END;
GO
-- Layercake.silv_data_anomaly (src/sql/Layercake/Tables/Layercake.silv_data_anomaly.sql)
IF OBJECT_ID(N'Layercake.silv_data_anomaly', N'U') IS NULL
BEGIN
    /*====================================================================
        Layercake.silv_data_anomaly
        Silver layer - table, keys and intrinsic indexes
    ====================================================================*/

    ----------------------------------------------------
    --  Layercake.silv_data_anomaly
    --  Rows where the data does not match the agreed rules. Re-derived every
    --  silver run; synced on anomaly_nk (type + contact_no). Never hard-
    --  deleted: a row that stops being detected is stamped resolved_at, and
    --  re-opened (resolved_at cleared) if it recurs.
    --
    --  Most types record where the derivation had to TOLERATE bad data - the
    --  contact still counts. NO_RICS_RECORD and NO_TRANSACTIONS are the
    --  exceptions: each records a contact the silv_member_base driver
    --  REMOVED (no membership record behind it / no transaction history at
    --  all), so they are both the audit trail for the exclusion and the
    --  lists fed back to the client. NO_TRANSACTIONS is raised only where
    --  the removed contact had a valid enrolment or election - the removal
    --  contradicts something, which is what makes it worth reporting.
    --  JOIN_NO_PAYMENT is the third exclusion type: the contact stays in
    --  the base, but has no paid invoice position in
    --  Subs.vwSubsMemberStatuses in any campaign year, so module 9 withholds
    --  its Join event and no state range opens on the enrolment / election
    --  date.
    --  ENROLMENT_AFTER_FIRST_PAID records a CORRECTION rather than an
    --  exclusion: the recorded enrolment date sat in a later campaign year
    --  than the contact's first paid position, so the silv_member_base
    --  driver backdated it to the first paid year (keeping the recorded
    --  date on the row). The Join lands where the paying started and the
    --  later paid years derive as Renewals. ELECTION_AFTER_FIRST_PAID is
    --  the same correction for a contact with no enrolment date, whose
    --  election is the Join anchor and was backdated instead.
    --  ENROLMENT_BEFORE_FIRST_PAID / ELECTION_BEFORE_FIRST_PAID are the
    --  same correction in the other direction: the recorded date sat in a
    --  campaign year with no paid position, earlier than the first paid
    --  one, and was moved FORWARD to it - only where the recorded year is
    --  inside the payment history. ELECTION_BEFORE_FIRST_PAID also covers
    --  an election carried forward with an enrolment that moved past it.
    ----------------------------------------------------
    create table Layercake.silv_data_anomaly
    (
        anomaly_id        int identity not null constraint pk_silv_data_anomaly primary key,
        anomaly_nk        nvarchar(240) not null,        -- '<type>:<contact_no>'
        anomaly_type      varchar(40)   not null,
        contact_no        nvarchar(200) not null,
        source_enr_id     uniqueidentifier null,         -- offending enrolment row, where one exists
        detail            nvarchar(400) null,
        first_detected_at datetime2(3)  not null constraint df_silv_data_anomaly_first default sysdatetime(),
        last_seen_at      datetime2(3)  not null constraint df_silv_data_anomaly_seen  default sysdatetime(),
        resolved_at       datetime2(3)  null
    );

    create unique nonclustered index ux_silv_data_anomaly_nk
        on Layercake.silv_data_anomaly (anomaly_nk);

    create nonclustered index ix_silv_data_anomaly_type
        on Layercake.silv_data_anomaly (anomaly_type)
        include (contact_no, resolved_at);
END;
GO
-- Layercake.silv_member_base (src/sql/Layercake/Tables/Layercake.silv_member_base.sql)
IF OBJECT_ID(N'Layercake.silv_member_base', N'U') IS NULL
BEGIN
    /*====================================================================
        Layercake.silv_member_base
        Silver layer - table, keys and intrinsic indexes
    ====================================================================*/

    /*====================================================================
        6. SILVER - derived tables
    ====================================================================*/

    ----------------------------------------------------
    --  Layercake.silv_member_base
    --  The per-contact base that every other silver derivation reads:
    --  effective enrolment/election dates (real rows first, curated
    --  ref_enrolment_exception dates as fallback, then the enrolment date
    --  backdated to the first paid campaign year where the subs history
    --  starts earlier), the lapse state after the stale-date invalidation,
    --  and the resolved country / gender / rpq-variant / lapse-reason
    --  surrogate keys.
    --
    --  Shape history:
    --    * 20260915_01 - recorded_enrolment_date and
    --      enrolment_from_subs_history added for the subs-history
    --      backdating: where the recorded enrolment date (real row or 07
    --      fallback) sits in a later campaign year than the contact's first
    --      paid position in silv_payment_events, enrolment_date is moved to
    --      that first paid year and the date the source recorded is kept
    --      alongside. Reported as ENROLMENT_AFTER_FIRST_PAID by module 10.
    --    * 20260915_02 - recorded_election_date and
    --      election_from_subs_history added: the same backdating for a
    --      contact with NO enrolment date, whose election is therefore the
    --      Join anchor (Join/RPQ, or the Change that opens the range).
    --      Reported as ELECTION_AFTER_FIRST_PAID by module 10.
    --    * No shape change, meaning widened: the same four columns now also
    --      carry a move FORWARD - a recorded date in a campaign year with no
    --      paid position, earlier than the first paid one and inside the
    --      payment history, is moved to the first paid year (and an election
    --      the enrolment moved past is carried with it). recorded > effective
    --      = backdated, recorded < effective = moved forward; reported as
    --      ENROLMENT_ / ELECTION_BEFORE_FIRST_PAID. The rule and its bound
    --      are in usp_load_silv_member_base.
    --
    --  Owned by 12_modules_silver.sql (usp_load_silv_member_base). It is a
    --  full re-derive each run - truncate + insert inside one transaction -
    --  and is read by the membership-events, data-anomaly, member-profile
    --  and annual-rate-base modules.
    --
    --  This table is the persisted form of what was the #mbase temp table
    --  inside the monolithic usp_load_silver. It exists because a #temp
    --  table cannot cross a stored-procedure boundary, and the per-table
    --  module split needs those four consumers to read the same derivation
    --  without rebuilding it three more times.
    --
    --  DELIBERATELY NOT UNIQUE ON contact_no: #mbase carried a NON-unique
    --  clustered index, and duplicate Rics_contactno values were caught
    --  downstream by the #ev_stage primary key and the #prof_stage unique
    --  index, which fail the load loudly with a clear message ("fix the
    --  duplicate contact, don't silently pick one"). Keeping this index
    --  non-unique keeps that failure in the same place with the same
    --  diagnostics. Making it unique would surface the problem one module
    --  earlier - a reasonable change, but a behaviour change.
    ----------------------------------------------------
    create table Layercake.silv_member_base
    (
        contact_id               uniqueidentifier not null,
        contact_no               nvarchar(200) not null,
        enrolment_date           date null,             -- EFFECTIVE enrolment date: earliest clamped real row, else 07 fallback, then moved to the first paid campaign year where that differs (backdated; or forward, inside the payment history only)
        election_date            date null,             -- EFFECTIVE election date: earliest real row, else 07 fallback; moved to the first paid campaign year where there is NO enrolment date (same rule), or carried forward with an enrolment date that moved past it
        is_rpq                   int  not null,         -- from the row supplying the earliest election date
        election_enr_id          uniqueidentifier null, -- ENR ID behind that election (anomaly detail)
        enrolment_from_exception int  not null,         -- 1 = the recorded enrolment date came from ref_enrolment_exception
        election_from_exception  int  not null,         -- 1 = election date came from ref_enrolment_exception
        recorded_enrolment_date  date null,             -- the enrolment date the source recorded (real row or 07 fallback) WHEN it was moved, either direction; null otherwise
        enrolment_from_subs_history int not null constraint df_silv_member_base_enr_subs default 0,   -- 1 = enrolment_date was moved to the first paid campaign year, backdated or forward (recorded_enrolment_date holds the original)
        recorded_election_date   date null,             -- the election date the source recorded (real row or 07 fallback) WHEN it was moved, either direction; null otherwise
        election_from_subs_history int not null constraint df_silv_member_base_elec_subs default 0,  -- 1 = election_date was moved to the first paid campaign year: as the Join anchor (no enrolment date), or carried forward with the enrolment (recorded_election_date holds the original)
        contact_lapsed_date      date null,             -- RAW contact lapse date (stale-lapse anomaly check)
        lapsed_date              date null,             -- ...invalidated if the member re-enrolled/was elected since
        lapse_reason_id          int  not null,         -- -> silv_ref_lapse_reason (0 = Not recorded)
        lapse_reason_name        nvarchar(700) null,    -- carried so the Lapse event subtype needs no re-join
        retirement_date          date null,             -- drives Practising / Retired
        source_enr_id            uniqueidentifier null, -- lineage: row that supplied the earliest qualifying date
        rpq_variant_id           int  not null,         -- -> silv_ref_rpq_variant (0 = N/A)
        country_id               int  not null,         -- -> silv_ref_country (0 = N/A)
        gender_id                int  not null          -- -> silv_ref_gender (0 = N/A)
    );

    -- non-unique by design - see the note above
    create clustered index cx_silv_member_base on Layercake.silv_member_base (contact_no);
END;
GO
-- Layercake.silv_member_profile (src/sql/Layercake/Tables/Layercake.silv_member_profile.sql)
IF OBJECT_ID(N'Layercake.silv_member_profile', N'U') IS NULL
BEGIN
    /*====================================================================
        Layercake.silv_member_profile
        Silver layer - table, keys and intrinsic indexes
    ====================================================================*/

    ----------------------------------------------------
    --  Layercake.silv_member_profile
    --  Per-contact reporting attributes needed by the DETAIL daily count.
    --  Diff-synced so attribute changes are DETECTED - they are logged to
    --  etl_daily_count_pending_rebuild rather than triggering a history
