-- Layercake.silv_member_state_ranges (src/sql/Layercake/Tables/Layercake.silv_member_state_ranges.sql)
IF OBJECT_ID(N'Layercake.silv_member_state_ranges', N'U') IS NULL
BEGIN
    /*====================================================================
        Layercake.silv_member_state_ranges
        Silver layer - table, keys and intrinsic indexes
    ====================================================================*/

    ----------------------------------------------------
    --  Layercake.silv_member_state_ranges
    --  state_seq (02 v6) persists the per-contact same-day event ordering
    --  (enrolment -> election -> lapse -> readmission within a day), so
    --  zero-length ranges (valid_from = valid_to) are unambiguous.
    --
    --  The natural-key index is created here in its FINAL form: unique, with
    --  the remaining columns INCLUDEd so the stage-vs-target EXCEPT
    --  comparisons in usp_load_silver read only this index (05 widens it
    --  in place on existing deploys; here it is created wide from the start).
    ----------------------------------------------------
    create table Layercake.silv_member_state_ranges
    (
        id                 int identity not null constraint pk_silv_member_state_ranges primary key,
        contact_no         nvarchar(200) not null,
        valid_from         date not null,
        valid_to           date null,
        campaign_year_from int not null,
        grade              varchar(12) not null,   -- enrolment, election, lapse
        region             varchar(12) not null,
        state_seq          int null                -- same-day event ordering
    );

    create unique nonclustered index ix_contact_no_valid_from_to_grade
        on Layercake.silv_member_state_ranges (contact_no, valid_from, valid_to, grade)
        include (campaign_year_from, region);
END;
GO
-- Layercake.silv_membership_events (src/sql/Layercake/Tables/Layercake.silv_membership_events.sql)
IF OBJECT_ID(N'Layercake.silv_membership_events', N'U') IS NULL
BEGIN
    /*====================================================================
        Layercake.silv_membership_events
        Silver layer - table, keys and intrinsic indexes
    ====================================================================*/

    ----------------------------------------------------
    --  Layercake.silv_membership_events
    --  All five lifecycle event types (Join, Change, Lapse, Readmission,
    --  Renewal). Because Lapse/Renewal/Readmission/Change events do not come
    --  from a single enrolment record, the incremental diff key is event_nk,
    --  a deterministic natural key built per event type (see 02). event_id is
    --  stable across runs; source_enr_id stays as informational lineage for
    --  Join events only.
    ----------------------------------------------------
    create table Layercake.silv_membership_events
    (
        event_id             int identity not null constraint pk_silv_membership_events primary key,
        event_nk             nvarchar(220) not null,        -- incremental diff key
        event_type           varchar(20) not null,          -- Join / Change / Lapse / Readmission / Renewal
        event_subtype        varchar(20) not null,
        event_date           date not null,
        source_enr_id        uniqueidentifier null,         -- Join events only
        contact_no           nvarchar(200) not null,
        grade_id             int not null,
        assessment_route_id  int not null,
        rpq_variant_id       int not null,
        hpb_id               int not null,
        country_id           int not null,
        gender_id            int not null,
        membership_status_id int not null,
        campaign_year        int not null,
        campaign_quarter     char(2) not null
    );

    -- primary incremental diff key
    create unique nonclustered index ux_silv_membership_events_nk
        on Layercake.silv_membership_events (event_nk);

    -- guards Join-event uniqueness (one Join event per enrolment record;
    -- Join events are per contact and JC/JR are mutually exclusive per contact)
    create unique nonclustered index ux_silv_membership_events_enr
        on Layercake.silv_membership_events (source_enr_id)
        where source_enr_id is not null;
END;
GO
-- Layercake.silv_payment_events (src/sql/Layercake/Tables/Layercake.silv_payment_events.sql)
IF OBJECT_ID(N'Layercake.silv_payment_events', N'U') IS NULL
