-- Layercake.silv_ref_lapse_reason (src/sql/Layercake/Tables/Layercake.silv_ref_lapse_reason.sql)
IF OBJECT_ID(N'Layercake.silv_ref_lapse_reason', N'U') IS NULL
BEGIN
    /*====================================================================
        Layercake.silv_ref_lapse_reason
        Silver layer - table, keys and intrinsic indexes
    ====================================================================*/

    -- apuk_lapsecode resolved to a description; feeds the Lapse event subtype
    -- (Resigned / Deceased / Expelled / Removed / ...). Loaded insert/update-only
    -- from brnz_option_set (OptionSetName = 'apuk_lapsecode').
    create table Layercake.silv_ref_lapse_reason
    (
        id          int identity not null constraint pk_silv_ref_lapse_reason primary key,
        lapse_code  int not null,
        reason_name nvarchar(700) not null,
        constraint uq_silv_ref_lapse_reason unique (lapse_code)
    );
END;
GO
-- Layercake.silv_ref_membership_grade (src/sql/Layercake/Tables/Layercake.silv_ref_membership_grade.sql)
IF OBJECT_ID(N'Layercake.silv_ref_membership_grade', N'U') IS NULL
BEGIN
    /*====================================================================
        Layercake.silv_ref_membership_grade
        Silver layer - table, keys and intrinsic indexes
    ====================================================================*/

    /*====================================================================
        3. SILVER - reference tables
        ------------------------------------------------------------------
        Identity surrogate keys, loaded insert/update-only (members are
        never deleted; names/regions are updated in place) so the ids stay
        STABLE between runs - the incremental gold facts depend on that.
        Unique natural-key constraints let the load match without touching
        the surrogate.
    ====================================================================*/

    create table Layercake.silv_ref_membership_grade
    (
        id          int identity not null constraint pk_silv_ref_membership_grade primary key,
        grade_name  varchar(24) not null,
        constraint uq_silv_ref_membership_grade unique (grade_name)
    );
END;
