-- Layercake.vw_enrolment_base (src/sql/Layercake/Views/Layercake.vw_enrolment_base.sql)
GO
/*====================================================================
    Layercake.vw_enrolment_base
    Silver layer - view
====================================================================*/

/*====================================================================
    THE QUALIFYING ENROLMENT / ELECTION ROW SET  (was #enr_base,
    inline inside usp_load_silv_member_base)
    ------------------------------------------------------------------
    One row per brnz_enrolment row that qualifies under EITHER the
    valid-enrolment rules (part 1) or the election rules (part 2). This
    is the single definition of "a valid enrolment or election" in the
    whole pipeline.

    IT LIVES HERE BECAUSE TWO MODULES NEED IT:
      * module 8  (usp_load_silv_member_base) stages it into #enr_base
        and derives the per-contact enrolment/election dates from it;
      * module 10 (usp_load_silv_data_anomaly) needs the same test to
        decide whether a contact the driver EXCLUDED nevertheless had a
        valid enrolment or election - which is what makes the exclusion
        worth reporting.
    These rules change (routes added 04/03/2024, the 14-day cool-off,
    the expanded application-type list), so a second copy would drift
    and the anomaly report would silently stop matching the driver.

    NOTE ON THE OBJECT FORM: this is a plain view - it is expanded into
    the calling query and optimised as part of it, exactly as the
    original sub-select was, so it costs nothing over inlining the two
    statements at each call site. It takes no parameters, so a view is
    all the callers ever needed; it is deliberately NOT a function,
    because the deployment account on the client database has no rights
    to create one. Callers that read it more than once should still
    SELECT INTO a #temp and index it, as module 8 does.

    PART 1 - ENROLMENT-SUPPLYING rows, under the FULL valid-view rules.
    Notes vs the RICS valid-enrolment view - the client's own definition
    upstream, not this object:
      * Application types are matched by NAME (bronze lands the display
        name, not the Application Type ID that view filters on). NULL
        application types are excluded - that view's NOT IN does the
        same (its "IS NULL temp inclusion" is commented out there).
      * Direct Entry is deliberately NOT in the exclusion list
        (removed from that view 06/03/2024, US 55324-related).
      * Enrolment dates before 1980-01-01 are CLAMPED to 1980-01-01,
        exactly as that view does.
      * 14-day cool-off (U/S 55339): a row whose End Date falls within
        14 days of the (clamped) enrolment date is a cooling-off
        cancellation, i.e. a non-payer - excluded.
      * No state-code filter, mirroring that view (taken out 17/11/2023).
    election_date is deliberately null on these rows: an election can
    only be supplied by a Part-2 row. These rows are never RPQ.

    PART 2 - ELECTION-SUPPLYING rows. The valid-enrolment rules do NOT
    apply to elections. Filters per 'Correct logic for join events':
      * election date present;
      * EXPANDED application-type exclusion list (21 types), NOT IN
        semantics so a NULL application type is excluded;
      * the 'Registered Valuer Top Up' route never supplies an election.
    is_rpq flags a Recognised Professional Qualification application, or
    an Assoc application on the Associate RPQ route.
    The row's own enrolment date (when present, clamped) is carried and
    feeds the per-contact earliest-enrolment aggregate - EXCEPT on an RPQ
    row, which carries none. An RPQ application IS a direct entry: the
    member never enrolled as a candidate, so a date in that row's
    Enrolment Date column is an artefact of how the application record
    was created, not a candidacy. It used to be carried unconditionally,
    and that defeated the Join/RPQ rule in module 9 - that rule asks for
    an election with no QUALIFYING enrolment date anywhere, but tests
    silv_member_base.enrolment_date, which this aggregate feeds. A direct
    entry whose election row happened to carry an enrolment date was
    therefore derived as Join/Candidate + Change rather than Join/RPQ,
    and module 10 logged it as RPQ_WITH_ENROLMENT on the strength of a
    "qualifying enrolment" that had never passed the Part-1 rules.
    A REAL candidacy is unaffected: it has a Part-1 row of its own, and
    the aggregate still finds it. So does a date riding on a NON-RPQ
    election row - only the direct-entry case is excluded.

    A contact can appear on both sides, and the same ENR ID can appear
    once per side - that is by design, and module 8's per-contact
    aggregate is what collapses it.
====================================================================*/
create or alter view Layercake.vw_enrolment_base
as
    -- Part 1 of 2: ENROLMENT-SUPPLYING rows
    -- (this branch names every column - a view takes its column names
    --  from the first arm of the union, so part 2 does not repeat them)
    select
        e.[ENR ID],
        e.[Contact No],
        d.enrolment_date,                       -- clamped, cast to date
        cast(null as date) as election_date,
        e.[Status Code],
        e.[Route ID],
        rt.apuk_name       as route_name,
        e.[Application Type],
        e.[Created DateTime],
        cast(0 as bit)     as is_rpq
    from Layercake.brnz_enrolment e
    left join Layercake.brnz_route rt
        on  rt.apuk_routeid = e.[Route ID]
        and rt._is_deleted  = 0
    cross apply (select cast(iif(e.[Enrolment Date] < '19800101', '19800101', e.[Enrolment Date]) as date) as enrolment_date) d
    where e._is_deleted = 0
      and e.[Enrolment Date] is not null
      -- route allowlist (Route replaces Enrolment Type as per meeting 17/11/2023)
      and e.[Route ID] in (
          '0504153D-6716-4C23-874E-32E2E2C4E3BF',   -- APC Other
          'B0CDFF73-5825-4E73-9852-EBC6B88448E1',   -- APC Prelim
          'E2231B53-7181-4AD8-BE15-3DAED8F0727F',   -- APC Research
          '6942A086-7EF8-48E7-993F-B0148F419117',   -- APC Structured Training 12
          '916E1056-C88B-4055-88A3-9FD0B57A98E7',   -- APC Structured Training 24
          '058D1F92-BD26-48AC-8603-8CC98B7DDA8E',   -- Associate Assessment
          'D4AC2D23-E733-4B2D-9693-2D1D2A0ACF46',   -- Senior Professional Assessment - 2017
          '7B867DC6-8F1F-4503-8A07-BFABDDD03CB2',   -- Specialist Assessment
          '2037C0AD-008D-48EE-B05A-9C90B4D61504')   -- Academic (added 04/03/2024, US 55324)
      -- application-type exclusions (by name; nulls excluded - see note above)
      and e.[Application Type] is not null
      and e.[Application Type] not in (
          'Chartered Alternative Designation',
          'Alternative Designation',
          'Apprenticeship',
          'Credential Application',
          'Fellowship',
          'Honorary',
          'Re-admission',
          'Scheme',
          'Student')
      -- ended without an election -> not a valid enrolment
      and not (e.[Election Date] is null and e.[End Date] is not null)
      -- 14-day cool-off cancellation -> non-payer, excluded (U/S 55339)
      and (e.[End Date] is null or e.[End Date] > dateadd(day, 14, d.enrolment_date))

    union all

    -- Part 2 of 2: ELECTION-SUPPLYING rows
    select
        e.[ENR ID],
        e.[Contact No],
        -- no enrolment date off an RPQ row - a direct entry never enrolled
        -- (see the header). Clamped as in part 1 on every other row.
        cast(case when r.is_rpq = 1 then null
                  else iif(e.[Enrolment Date] < '19800101', '19800101', e.[Enrolment Date])
             end as date),
        cast(e.[Election Date] as date),
        e.[Status Code],
        e.[Route ID],
        rt.apuk_name,
        e.[Application Type],
        e.[Created DateTime],
        r.is_rpq
    from Layercake.brnz_enrolment e
    left join Layercake.brnz_route rt
        on  rt.apuk_routeid = e.[Route ID]
        and rt._is_deleted  = 0
    -- computed once: the flag is both a returned column and the test that
    -- decides whether this row supplies an enrolment date
    cross apply (select cast(case when e.[Application Type] = 'Recognised Professional Qualification'
                                    or (e.[Application Type] = 'Assoc' and rt.apuk_name = 'Associate RPQ')
                                  then 1 else 0 end as bit) as is_rpq) r
    where e._is_deleted = 0
      and e.[Election Date] is not null
      -- expanded exclusion list (nulls excluded by NOT IN semantics)
      and e.[Application Type] not in (
          'Student',
          'Scheme',
          'Chartered Alternative Designation',
          'Accreditation Application',
          'Additional Role',
          'Alternative Designation',
          'Appeal',
          'Apprenticeship',
          'Complaint Report',
          'Concession',
          'Credential Application',
          'Deceased',
          'Deferral Application',
          'Fixed Penalty Review',
          'Mentor',
          'Re-admission',
          'Recognised Qualification',
          'Removal',
          'Resignation',
          'Route Change',
          'Fellowship')
      and isnull(rt.apuk_name, '') <> 'Registered Valuer Top Up';
GO
-- Layercake.vw_student_superseded (src/sql/Layercake/Views/Layercake.vw_student_superseded.sql)
GO
/*====================================================================
    Layercake.vw_student_superseded
    Silver layer - view
====================================================================*/

/*====================================================================
    STUDENTS WHO HAVE MOVED ON TO A QUALIFYING ENROLMENT
    ------------------------------------------------------------------
    One row per contact number whose Student status has been SUPERSEDED
    in the enrolment history: the most recently created Student
    application is ended, and a qualifying enrolment or election row
    (Layercake.vw_enrolment_base) was created on or after it.

    WHY IT EXISTS. The silv_member_base driver excludes a contact whose
    latest rics record carries the Student grade (200000003, 'Rules to
    note' #2). Reconciliation found contacts where that grade is STALE:
    the Student enrolment was closed and an APC / Associate enrolment
    opened - typically on the same day, minutes apart - but the rics
    record (and CE.vwContact.MemberGrade_Description) still says
    Student. Those contacts are members by every other reading, so the
    grade alone must not remove them. This view names the cohort; the
    driver keeps a contact in it despite the grade.

    THE TEST, per contact:
      1. the Student application-type row created LAST - [Created
         DateTime] then [ENR ID], never [Created Date] or [Enrolment
         Date]: the Student row and its replacement are routinely
         created on the same day, so only the datetime orders them;
      2. that row has an [End Date] - the student period is over;
      3. at least one vw_enrolment_base row (a valid enrolment or an
         election, under the full rules there) was created at or after
         the Student row's [Created DateTime]. A Student row is never in
         vw_enrolment_base - both parts exclude the type - so the
         superseding row is always a different application.
    A Student row created AFTER the qualifying one blocks the override
    (it is the row step 1 picks, and nothing follows it), so a member
    who has gone back to being a student stays excluded. A Student row
    that is still open never overrides, whatever else exists.

    Nothing about payments is tested here: an overridden contact still
    has to hold a paid position to receive a Join (module 9), exactly
    like any other member-base row.

    Shared, like vw_enrolment_base, because the same test is applied
    by the driver (usp_load_silv_member_base), by rule 6 of
    usp_load_silv_data_anomaly, and by the reconciliation scripts under
    Scripts/Reconciliation - one definition, so they cannot drift. A
    view, not a function, for the reason given on vw_enrolment_base.
====================================================================*/
create or alter view Layercake.vw_student_superseded
as
    select
        s.[Contact No],
        s.[ENR ID]                  as student_enr_id,
        s.[Created DateTime]        as student_created,
        cast(s.[End Date] as date)  as student_end_date,
        q.[ENR ID]                  as superseding_enr_id,
        q.[Created DateTime]        as superseding_created
    from (
        -- 1. the most recently created Student application per contact
        select
            e.[Contact No],
            e.[ENR ID],
            e.[Created DateTime],
            e.[End Date],
            row_number() over (partition by e.[Contact No]
                               order by e.[Created DateTime] desc, e.[ENR ID]) as n
        from Layercake.brnz_enrolment e
        where e._is_deleted = 0
          and e.[Contact No] is not null
          and e.[Application Type] = 'Student'
    ) s
    -- 3. the first qualifying row created at or after it (cross apply:
    --    no such row, no output row)
    cross apply (
        select top (1) v.[ENR ID], v.[Created DateTime]
        from Layercake.vw_enrolment_base v
        where v.[Contact No]       = s.[Contact No]
          and v.[Created DateTime] >= s.[Created DateTime]
        order by v.[Created DateTime], v.[ENR ID]
    ) q
    where s.n = 1
      -- 2. the student period is over
      and s.[End Date] is not null;
GO
-- Layercake.usp_etl_log_end (src/sql/Layercake/Procedures/Layercake.usp_etl_log_end.sql)
GO
/*====================================================================
    Layercake.usp_etl_log_end
    Control - ETL logging / progress
====================================================================*/

create or alter procedure Layercake.usp_etl_log_end
    @log_id         bigint,
    @status         varchar(10),
    @rows_inserted  int = null,
    @rows_updated   int = null,
    @rows_deleted   int = null,
    @error_message  nvarchar(4000) = null
as
begin
    set nocount on;
    update Layercake.etl_run_log
    set finished_at   = sysdatetime(),
        status        = @status,
        rows_inserted = @rows_inserted,
        rows_updated  = @rows_updated,
        rows_deleted  = @rows_deleted,
        error_message = @error_message
    where log_id = @log_id;
end
GO
-- Layercake.usp_etl_log_pending_rebuild (src/sql/Layercake/Procedures/Layercake.usp_etl_log_pending_rebuild.sql)
GO
/*====================================================================
    Layercake.usp_etl_log_pending_rebuild
    Control - ETL logging / progress
====================================================================*/

/*************************************************************************************
    12 - SILVER MODULES: one stored procedure per silver table
    ---------------------------------------------------------------------------------
    Splits the monolithic Layercake.usp_load_silver (02_usp_load_silver_v9.sql)
    into fourteen independent modules plus one shared helper. The orchestrator
    that calls them in order lives in 14_orchestrators.sql and keeps the name
    Layercake.usp_load_silver with an unchanged signature.

    All derivation logic is carried over verbatim from v9. Two structural
    changes were REQUIRED to make the modules independent - both are described
    in full below, because they are the only places where behaviour could
    differ from the monolith.

    ---------------------------------------------------------------------------------
    CHANGE 1: #mbase is now a persisted table, Layercake.silv_member_base
    ---------------------------------------------------------------------------------
    In the monolith, #mbase (the per-contact base: effective enrolment/election
    dates, lapse state, country/gender/rpq keys) was built once inside the
    membership-events step and then reused by the member-profile and annual-rate
    steps. A #temp table cannot cross a procedure boundary, so it is now built by
    its own module - usp_load_silv_member_base - into a real table, and the four
    consumers read that table instead:

        usp_load_silv_membership_events    (all six event derivations)
        usp_load_silv_data_anomaly         (all four rule checks)
        usp_load_silv_member_profile       (the profile stage)
        usp_load_silv_annual_rate_base     (boundary headcounts)

    The derivation itself is byte-for-byte the v9 #mbase query; only the target
    changed. #enr_base and #rics_record, which feed it and are used nowhere else,
    stay as #temp tables inside that module.

    COST: one extra table write per run (one row per eligible contact). The
    build is unchanged - it ran once per run before and still does.

    NOT UNIQUE ON contact_no BY DESIGN: #mbase carried a NON-unique clustered
    index, and duplicate Rics_contactno values were caught downstream by the
    #ev_stage primary key and the #prof_stage unique index, which fail the load
    loudly with a clear message. silv_member_base keeps a non-unique clustered
    index for exactly that reason, so a duplicate contact still fails in the
    same place with the same diagnostics. Making it unique would surface the
    problem one module earlier - a reasonable change, but a behaviour change, so
    it is deliberately not made here.

    ---------------------------------------------------------------------------------
    CHANGE 2: the retro-change log is written by each producer, not by step 6
    ---------------------------------------------------------------------------------
    In the monolith, steps 3 / 5 / 5b each computed a local variable
    (@pay_recalc_from, @rng_recalc_from, @prof_recalc_from) holding the earliest
    already-loaded date their changes reached back into, and step 6a wrote all
    three to Layercake.etl_daily_count_pending_rebuild in one go. Local variables
    cannot cross a procedure boundary either, so that write is now performed by
    each producing module through a shared helper:

        Layercake.usp_etl_log_pending_rebuild @run_id, @source, @affected_from

    The helper contains step 6a's logic unchanged for a single source: clamp
    affected_from to the spine start (2020-10-01), write nothing unless the date
    actually reaches into a marked-loaded date, then keep at most one OPEN row
    per source holding the EARLIEST date seen.

    Two consequences, both benign:
      * The pending row is now written inside the producing module's own
        transaction, so the detected change and its log entry commit or roll
        back together. In the monolith the change committed first and the log
        entry followed in a separate transaction.
      * Its progress message attaches to the producing step's log_id rather than
        to the daily-count step's. The rows written are identical.

    usp_load_silv_daily_count therefore implements 6b-6e only (rebuild request,
    work list, chunked walk, pending-rebuild close-off).

    ---------------------------------------------------------------------------------
    ONE MODULE COVERS TWO TABLES: usp_load_silv_daily_count
    ---------------------------------------------------------------------------------
    silv_daily_count_detail and silv_daily_count are loaded by a single module,
    deliberately. Per chunk, the detail rows are deleted and re-inserted, the
    main rows are re-derived as a plain SUM over that same detail, and the
    chunk's dates are marked in etl_daily_count_loaded - all inside ONE
    transaction. That is what makes the marker trustworthy in both directions
    and lets a failed run resume: at any commit boundary the two tables
    reconcile for every loaded date. Splitting them into two modules would need
    either two independent marker tables or a second full pass over the spine,
    and would break the guarantee in between. The main table is a pure aggregate
    of the detail, so there is no separate derivation to isolate.

    ---------------------------------------------------------------------------------
    STATIC REFERENCE TABLES HAVE NO MODULE
    ---------------------------------------------------------------------------------
    silv_ref_membership_grade, silv_ref_gender and silv_ref_membership_status are
    seeded once by baseline_ddl.sql (and 00_schema_and_control) and are never
    loaded from source - the monolith did not touch them either, so there is
    nothing to modularise.

    ---------------------------------------------------------------------------------
    LOGGING
    ---------------------------------------------------------------------------------
    Every module opens its own etl_run_log step. Step names match the target
    table, so monitoring queries keep working - with one change: the monolith
    logged all four loaded reference tables under the single step name
    'silv_ref_tables'; each now logs under its own table name.

    Modules, in dependency order:
        0.  usp_etl_log_pending_rebuild        (helper, not a table load)
        1.  usp_load_silv_ref_assessment_route
        2.  usp_load_silv_ref_rpq_variant
        3.  usp_load_silv_ref_country
        4.  usp_load_silv_ref_lapse_reason
        5.  usp_load_ref_date_spine
        6.  usp_load_ref_campaign_year_config
        7.  usp_load_silv_payment_events
        8a. usp_load_ref_enrolment_exception   (added 20260928_02)
        8.  usp_load_silv_member_base
        9.  usp_load_silv_membership_events
        10. usp_load_silv_data_anomaly
        11. usp_load_silv_member_state_ranges
        12. usp_load_silv_member_profile
        13. usp_load_silv_daily_count          (+ silv_daily_count_detail)
        14. usp_load_silv_annual_rate_base

    DEPLOY NOTE: requires baseline_ddl.sql (for Layercake.silv_member_base) and
    06_etl_progress_tracking.sql. Remove 02_usp_load_silver_v9.sql (and any
    earlier version) from the deploy folder so run-scripts.ps1 does not also
    create the monolithic version. 14 recreates Layercake.usp_load_silver as the
    orchestrator.
*************************************************************************************/

/*====================================================================
    0. HELPER: retro-change log (step 6a of the monolith, per source)
    ------------------------------------------------------------------
    A change detected by a producing module matters to the daily count
    only if it reaches back into dates that are ALREADY MARKED LOADED -
    those are the dates the daily run will no longer rebuild. Record the
    fact and carry on; @RebuildFrom / @FullRebuild applies it.

    affected_from is CLAMPED to the spine start: the derived dates come
    from event dates (enrolment dates clamp to 1980) and campaign-year
    first days, both of which routinely predate the spine. Without the
    clamp a pending row could hold e.g. 1980-01-01 and would never be
    satisfied by any rebuild - not even @FullRebuild, which starts at
    2020-10-01 - so it could never be stamped applied.

    Call INSIDE the producing module's transaction, so the detected
    change and this log entry commit together.
====================================================================*/
create or alter procedure Layercake.usp_etl_log_pending_rebuild
    @run_id        uniqueidentifier,
    @source        varchar(20),         -- state_ranges | payments | member_profile | enrol_exception
    @affected_from date,
    @logged        int = null output    -- 1 if a row was written/updated, else 0
as
begin
    set nocount on;

    set @logged = 0;

    if @affected_from is null return;

    if @affected_from < '20201001' set @affected_from = '20201001';

    -- nothing to record unless the change reaches an already-loaded date
    if not exists (select 1 from Layercake.etl_daily_count_loaded l
                   where l.[date] >= @affected_from)
        return;

    declare @detail nvarchar(400);

    -- an already-open row keeps the EARLIEST affected date seen
    update p
    set affected_from    = iif(@affected_from < p.affected_from, @affected_from, p.affected_from),
        detection_count  = p.detection_count + 1,
        last_detected_at = sysdatetime(),
        last_run_id      = @run_id,
        detail           = concat(N'Change detected affecting loaded dates from ',
                                  convert(nvarchar(10),
                                          iif(@affected_from < p.affected_from, @affected_from, p.affected_from), 23),
                                  N' - NOT rebuilt by the daily run; use @RebuildFrom to apply')
    from Layercake.etl_daily_count_pending_rebuild p
    where p.[source] = @source
      and p.applied_at is null;
    set @logged = @@rowcount;

    if @logged = 0
    begin
        set @detail = concat(N'Change detected affecting loaded dates from ',
                             convert(nvarchar(10), @affected_from, 23),
                             N' - NOT rebuilt by the daily run; use @RebuildFrom to apply');

        insert into Layercake.etl_daily_count_pending_rebuild
        ([source], affected_from, last_run_id, detail)
        values (@source, @affected_from, @run_id, @detail);
        set @logged = @@rowcount;
    end
end
GO
-- Layercake.usp_etl_log_progress (src/sql/Layercake/Procedures/Layercake.usp_etl_log_progress.sql)
GO
/*====================================================================
    Layercake.usp_etl_log_progress
    Control - ETL logging / progress
====================================================================*/

/*====================================================================
    Logging proc: one call = one durable row + one live message.
    @ts is IN/OUT: pass the sub-step start time in, get "now" back so the
    next sub-step's timer starts automatically.
====================================================================*/
create or alter procedure Layercake.usp_etl_log_progress
    @log_id   bigint,
    @substep  nvarchar(128),
    @rows     int = null,
    @ts       datetime2(3) output
as
begin
    set nocount on;

    declare @now datetime2(3) = sysdatetime();
    if @ts is null set @ts = @now;
    declare @ms bigint = datediff_big(millisecond, @ts, @now);

    insert into Layercake.etl_progress_log
        (log_id, substep, rows_affected, started_at, finished_at, duration_ms)
    values
        (@log_id, @substep, @rows, @ts, @now, @ms);

    -- live output: streams to the Messages tab immediately (severity 0 =
    -- informational, does not trip xact_abort or the caller's catch block)
    declare @step nvarchar(128) =
        isnull((select step_name from Layercake.etl_run_log with (nolock)
                where log_id = @log_id), N'?');

    declare @msg nvarchar(400) = concat(
        convert(varchar(8), @now, 108), N'  ',
        @step, N' | ', @substep,
        N' - ', format(@ms / 1000.0, '0.0'), N's',
        iif(@rows is not null, concat(N'  (', format(@rows, 'N0'), N' rows)'), N''));

    raiserror('%s', 0, 1, @msg) with nowait;

    set @ts = @now;     -- next sub-step's timer starts here
end
GO
-- Layercake.usp_etl_log_start (src/sql/Layercake/Procedures/Layercake.usp_etl_log_start.sql)
GO
/*====================================================================
    Layercake.usp_etl_log_start
    Control - ETL logging / progress
====================================================================*/

create or alter procedure Layercake.usp_etl_log_start
    @run_id     uniqueidentifier,
    @layer      varchar(12),
    @step_name  varchar(128),
    @log_id     bigint output
as
begin
    set nocount on;
    insert into Layercake.etl_run_log (run_id, layer, step_name)
    values (@run_id, @layer, @step_name);
    set @log_id = scope_identity();
end
GO
-- Layercake.usp_load_brnz_contact (src/sql/Layercake/Procedures/Layercake.usp_load_brnz_contact.sql)
GO
/*====================================================================
    Layercake.usp_load_brnz_contact
    Bronze layer - loads one table
====================================================================*/

/*************************************************************************************
    11 - BRONZE MODULES: one stored procedure per bronze table
    ---------------------------------------------------------------------------------
    Splits the monolithic Layercake.usp_load_bronze (01_usp_load_bronze.sql) into
    nine independent modules, one per target table. The orchestrator that calls
    them in order lives in 14_orchestrators.sql and keeps the name
    Layercake.usp_load_bronze, so nothing upstream changes.

    Each module is self-contained:
      * takes @run_id (generated if run standalone, so any module can be run on
        its own for a targeted reload);
      * opens its own etl_run_log step under the SAME step name the monolith
        used, so existing monitoring queries are unaffected;
      * runs its own transaction - a failure rolls back only that table;
      * logs the failure against its own step and re-throws, so the caller
        (orchestrator or SQL Agent / ADF) sees the error.

    The per-table sync pattern is UNCHANGED from 01 (see that file's header for
    the reasoning) - only the procedure boundaries are new:

      1. Snapshot the source into a keyed #temp.
      2. UPDATE changed payloads + resurrect soft-deleted rows that reappeared.
      3. INSERT rows not yet in bronze (backfills, not just yesterday).
      4. Soft-DELETE rows no longer in the source (_is_deleted = 1).
      5. Reconciliation check: active bronze rows must equal the snapshot.

    NO business filters here: test-record exclusion, statecode, approved = 1 and
    the Student apuk_membergrade exclusion all live in silver.

    The #temp tables are dropped automatically when each procedure returns, so
    the explicit cleanup the monolith needed between steps is gone.

    Modules, in dependency order (they are mutually independent - the order is
    only for readability and matches the monolith):
        1. usp_load_brnz_contact
        2. usp_load_brnz_enrolment
        3. usp_load_brnz_rics_record
        4. usp_load_brnz_local_group
        5. usp_load_brnz_cust_trans
        6. usp_load_brnz_subs_status
        7. usp_load_brnz_option_set
        8. usp_load_brnz_route
        9. usp_load_brnz_contact_test_record

    DEPLOY NOTE: remove 01_usp_load_bronze.sql from the deploy folder so
    run-scripts.ps1 does not also create the monolithic version. 14 recreates
    Layercake.usp_load_bronze as the orchestrator.
*************************************************************************************/

/*====================================================================
    1. CE.vwContact -> Layercake.brnz_contact
====================================================================*/
create or alter procedure Layercake.usp_load_brnz_contact
    @run_id uniqueidentifier = null
as
begin
    set nocount on;
    set xact_abort on;

    if @run_id is null set @run_id = newid();

    declare @log_id    bigint,
            @ins       int,
            @upd       int,
            @del       int,
            @src_count bigint,
            @tgt_count bigint,
            @err       nvarchar(4000);

    begin try
        exec Layercake.usp_etl_log_start @run_id, 'bronze', 'brnz_contact', @log_id output;
        begin tran;

        -- CreatedOn / StateCode added 20260928_01 for the enrolment-exception
        -- capture in silver (usp_load_ref_enrolment_exception) - see that
        -- module and the column comments in 02_Tables/Bronze.
        select ContactId, Rics_contactno, Rics_ElectionDate, Rics_LapsedDate,
               MemberGrade_Description, GenderCode, rics_countryid,
               CreatedOn, StateCode
        into #src_contact
        from CE.vwContact;
        create unique clustered index cx_src_contact on #src_contact (ContactId);

        -- changed payloads + reappeared rows
        update tgt
        set Rics_contactno          = s.Rics_contactno,
            Rics_ElectionDate       = s.Rics_ElectionDate,
            Rics_LapsedDate         = s.Rics_LapsedDate,
            MemberGrade_Description = s.MemberGrade_Description,
            GenderCode              = s.GenderCode,
            rics_countryid          = s.rics_countryid,
            CreatedOn               = s.CreatedOn,
            StateCode               = s.StateCode,
            _is_deleted             = 0,
            _deleted_at             = null,
            _updated_at             = sysdatetime()
        from Layercake.brnz_contact tgt
        join #src_contact s on s.ContactId = tgt.ContactId
        where tgt._is_deleted = 1
           or exists (select s.Rics_contactno, s.Rics_ElectionDate, s.Rics_LapsedDate,
                             s.MemberGrade_Description, s.GenderCode, s.rics_countryid,
                             s.CreatedOn, s.StateCode
                      except
                      select tgt.Rics_contactno, tgt.Rics_ElectionDate, tgt.Rics_LapsedDate,
                             tgt.MemberGrade_Description, tgt.GenderCode, tgt.rics_countryid,
                             tgt.CreatedOn, tgt.StateCode);
        set @upd = @@rowcount;

        -- new rows (also backfills anything missing, not just the last day)
        insert into Layercake.brnz_contact
        (ContactId, Rics_contactno, Rics_ElectionDate, Rics_LapsedDate,
         MemberGrade_Description, GenderCode, rics_countryid, CreatedOn, StateCode)
        select s.ContactId, s.Rics_contactno, s.Rics_ElectionDate, s.Rics_LapsedDate,
               s.MemberGrade_Description, s.GenderCode, s.rics_countryid,
               s.CreatedOn, s.StateCode
        from #src_contact s
        where not exists (select 1 from Layercake.brnz_contact t where t.ContactId = s.ContactId);
        set @ins = @@rowcount;

        -- rows gone from source -> soft delete
        update tgt
        set _is_deleted = 1, _deleted_at = sysdatetime(), _updated_at = sysdatetime()
        from Layercake.brnz_contact tgt
        where tgt._is_deleted = 0
          and not exists (select 1 from #src_contact s where s.ContactId = tgt.ContactId);
        set @del = @@rowcount;

        -- active rows must mirror the source snapshot exactly
        select @src_count = count(*) from #src_contact;
        select @tgt_count = count(*) from Layercake.brnz_contact where _is_deleted = 0;
        if @src_count <> @tgt_count
            raiserror('Row count mismatch after sync of Layercake.brnz_contact: source %I64d vs active target %I64d.', 16, 1, @src_count, @tgt_count);

        commit;
        exec Layercake.usp_etl_log_end @log_id, 'Success', @ins, @upd, @del;
    end try
    begin catch
        if xact_state() <> 0 rollback;
        set @err = concat(error_message(), ' (error ', error_number(), ', line ', error_line(), ')');
        if @log_id is not null
            exec Layercake.usp_etl_log_end @log_id, 'Failed', @ins, @upd, @del, @err;
        throw;
    end catch
end
GO
