-- Layercake.usp_load_silver (src/sql/Layercake/Procedures/Layercake.usp_load_silver.sql)
GO
/*====================================================================
    Layercake.usp_load_silver
    Orchestration - calls the per-table modules in order
====================================================================*/

/*====================================================================
    SILVER
    ------------------------------------------------------------------
    Build order: refs -> date spine -> campaign year config -> payment
    events -> enrolment exceptions -> member base -> membership events
    -> anomalies -> state ranges -> member profile -> daily counts ->
    annual rate base.

    Parameters (all passed straight through to the daily-count module,
    the only one that takes them):
      @run_id              - orchestrator run id (generated if standalone)
      @FullRebuild         - 1 clears the loaded markers for the WHOLE
                             spine (from 2020-10-01) so both daily count
                             tables are rebuilt from scratch by this
                             run's chunked walk. Refs / events / ranges /
                             rate base always self-correct regardless.
      @RebuildFrom         - clear the loaded markers from this date
                             forward and re-do those dates. The
                             deliberate way to apply a retrospective
                             correction flagged in
                             etl_daily_count_pending_rebuild. Ignored
                             when @FullRebuild = 1.
      @DailyCountBatchDays - chunk size for the daily-count walk, and
                             therefore the granularity at which a failed
                             run resumes (default 31; minimum 1).
====================================================================*/
create or alter procedure Layercake.usp_load_silver
    @run_id              uniqueidentifier = null,
    @FullRebuild         bit  = 0,
    @RebuildFrom         date = null,
    @DailyCountBatchDays int  = 31
as
begin
    set nocount on;
    set xact_abort on;

    if @run_id is null set @run_id = newid();

    -- reference tables: insert-new + update-in-place only, so surrogate ids
    -- stay stable and the incremental gold facts keep resolving
    exec Layercake.usp_load_silv_ref_assessment_route @run_id = @run_id;
    exec Layercake.usp_load_silv_ref_rpq_variant      @run_id = @run_id;
    exec Layercake.usp_load_silv_ref_country          @run_id = @run_id;
    exec Layercake.usp_load_silv_ref_lapse_reason     @run_id = @run_id;

    -- calendar: the config derives its campaign years from the spine
    exec Layercake.usp_load_ref_date_spine            @run_id = @run_id;
    exec Layercake.usp_load_ref_campaign_year_config  @run_id = @run_id;

    -- payments feed the Renewal / Readmission events and the daily paid count
    exec Layercake.usp_load_silv_payment_events       @run_id = @run_id;

    -- curated gap-fill dates for paying contacts with no qualifying enrolment
    -- or election row. BETWEEN THE TWO DELIBERATELY: the capture driver is the
    -- payment events above, and the member base below coalesces the result in.
    -- Insert-only for captures, flag-only for retirement - see the module
    -- header for why, and for how a new capture reaches the daily count.
    exec Layercake.usp_load_ref_enrolment_exception   @run_id = @run_id;

    -- the per-contact base every derivation below reads
    exec Layercake.usp_load_silv_member_base          @run_id = @run_id;

    -- events, then the rule checks over the same base
    exec Layercake.usp_load_silv_membership_events    @run_id = @run_id;
    exec Layercake.usp_load_silv_data_anomaly         @run_id = @run_id;

    -- ranges derive from the events; the profile's affected-date
    -- calculation reads the ranges, so it follows them
    exec Layercake.usp_load_silv_member_state_ranges  @run_id = @run_id;
    exec Layercake.usp_load_silv_member_profile       @run_id = @run_id;

    -- daily counts (detail + main, chunked and marked per chunk)
    exec Layercake.usp_load_silv_daily_count
         @run_id              = @run_id,
         @FullRebuild         = @FullRebuild,
         @RebuildFrom         = @RebuildFrom,
         @DailyCountBatchDays = @DailyCountBatchDays;

    -- segment-level annual counts for the DAX rate measures
    exec Layercake.usp_load_silv_annual_rate_base     @run_id = @run_id;
end
GO
-- Layercake.usp_run_daily_load (src/sql/Layercake/Procedures/Layercake.usp_run_daily_load.sql)
GO
/*====================================================================
    Layercake.usp_run_daily_load
    Orchestration - calls the per-table modules in order
====================================================================*/

/*====================================================================
    DAILY RUN
    ------------------------------------------------------------------
    Runs bronze -> silver -> gold under one run_id so the whole run can
    be traced in Layercake.etl_run_log.

    * Any layer failure stops the run (a layer must not build on a
      partial predecessor). The failed module, its error and every
      module before it are in the log.
    * Every module is a re-derive + diff, and the daily count is a
      load-what-isn't-marked walk, so recovery is simply re-running this
      proc - it picks up whatever the failed run didn't finish. No
      manual cleanup is ever needed.
    * @FullRebuild = 1 forces silv_daily_count / silv_daily_count_detail
      (and therefore the gold detail fact) to recompute from the start
      of the spine - use after changing business rules, otherwise leave
      at 0.

    Schedule daily, e.g.:
        exec Layercake.usp_run_daily_load;

    For a targeted retrospective rebuild, call the silver orchestrator
    (or the daily-count module) directly with @RebuildFrom - see the
    file header.
====================================================================*/
create or alter procedure Layercake.usp_run_daily_load
    @FullRebuild bit = 0
as
begin
    set nocount on;
    set xact_abort on;

    declare @run_id uniqueidentifier = newid(),
            @log_id bigint,
            @err    nvarchar(4000);

    exec Layercake.usp_etl_log_start @run_id, 'run', 'usp_run_daily_load', @log_id output;

    begin try
        -- each module manages its own transaction and step logging
        exec Layercake.usp_load_bronze @run_id = @run_id;
        exec Layercake.usp_load_silver @run_id = @run_id, @FullRebuild = @FullRebuild;
        exec Layercake.usp_load_gold   @run_id = @run_id;

        exec Layercake.usp_etl_log_end @log_id, 'Success';
    end try
    begin catch
        if xact_state() <> 0 rollback;
        set @err = concat(error_message(), ' (error ', error_number(), ', line ', error_line(), ')');
        exec Layercake.usp_etl_log_end @log_id, 'Failed', null, null, null, @err;
        throw;    -- surface to the scheduler so the job reports failure
    end catch
end
GO
-- src/sql/baseline/03_SeedData/seed-enrolment-exception.sql
/*************************************************************************************
    Layercake.ref_enrolment_exception - RETIRED (20260928_02)
    ---------------------------------------------------------------------------------
    THIS FILE NO LONGER CAPTURES ANYTHING. It is kept in phase 03 as a
    deliberate no-op so that the reason the capture left is where anyone
    adding a phase 03 capture back would look for it.

    THE CAPTURE NOW LIVES IN THE PIPELINE:
        Layercake.usp_load_ref_enrolment_exception   (silver module 8a)
        04_Programmability/StoredProcedures/Silver/

    Read that module's header for the driver, the derivation rules, the
    lifecycle and the review queries. Everything this file used to document is
    there, against the objects that own each rule rather than against
    hand-copied duplicates of them.

    ---------------------------------------------------------------------------------
    WHY IT MOVED

    This file populated the table only when it was EMPTY, and nothing in
    usp_run_daily_load ever touched it again. That made the table a frozen
    point-in-time snapshot on a live database, and a re-derivation against
    today's source on a -Fresh / -Reset Data rebuild. The two disagreed, and
    the disagreement showed up as a small, slowly growing variance on the most
    recent day's active and paid member counts:

      * A rebuild captured every contact who had started paying, or whose CE
        data had been corrected, since the original snapshot. A daily load
        did not.
      * An uncaptured contact of this kind does not merely lack a date. With
        no qualifying Layercake.vw_enrolment_base row AND no exception row,
        usp_load_silv_member_base gives it a null enrolment date and a null
        election date; both Join branches in usp_load_silv_membership_events
        require one of those; no Join means no state range; and the active
        count and BOTH paid counts are gated by the state-range join. So the
        contact is in none of them.

    There was a second, quieter reason. Phase 03 runs before bronze exists, so
    this file had to read the SOURCE views (Subs.vwSubsMemberStatuses,
    CE.vwContact, synapse_ce.vwEnrolments) and carry its own hand-copied copy
    of the qualifying rules - every route id and application type from
    vw_enrolment_base, repeated here and again in the maintenance top-up
    script. Three copies of one rule set, kept in step by hand. The silver
    module runs after bronze, so it reads vw_enrolment_base itself and carries
    no copy of anything: a fresh database and a live one now derive the same
    cohort by construction, which is the whole point of the move.

    ---------------------------------------------------------------------------------
    WHAT THIS MEANS OPERATIONALLY

      * A BLANK DATABASE gets no exception rows at deploy time. It gets them
        on the first `exec Layercake.usp_run_daily_load` instead, derived from
        bronze under the current rules. Since that first run is also the full
        historical backfill, the counts it produces already include them.
      * -Reset Data / truncate-all.sql still clear the table, and the next
        daily load re-captures it. `Deploy-Database.ps1 -Phase 03` no longer
        does - it is still required for the id-0 'N/A' seed rows.
      * EXISTING ROWS ON A LIVE DATABASE ARE UNTOUCHED by the move. The module
        is insert-only for captures, so no contact already captured loses or
        changes the dates their history was built on.
      * The one behaviour that is genuinely gone: this file's ability to
        RE-DERIVE the whole table under current rules by truncating it and
        running phase 03. To do that now, truncate the table and run a silver
        load - the module will capture the whole cohort from scratch. Treat it
        the way -Fresh is treated: test databases, and expect a retrospective
        rebuild to follow.

    The table definition, and the lifecycle the module implements, are in
    02_Tables/Silver/Layercake.ref_enrolment_exception.sql.
*************************************************************************************/

set nocount on;
go

print 'seed-enrolment-exception.sql: RETIRED, no action taken.';
print '  ref_enrolment_exception is maintained by Layercake.usp_load_ref_enrolment_exception';
print '  on every silver load. See this file''s header for why the phase 03 capture went.';
go
GO
-- src/sql/baseline/03_SeedData/seed-reference-data.sql
/*====================================================================
    Static reference seed data
    Post-deployment DML - the id-0 'N/A' members that make every
    foreign key resolve, plus the fixed gender and status lists.

    NOTE: unlike the object scripts, the guards here are DELIBERATELY
    RETAINED. This is DML, not DDL - a second run must not duplicate
    the rows. Every statement below is safe to re-run.
====================================================================*/

/*====================================================================
    Inserted once, never reloaded. Every reference table gets id 0 =
    'N/A' so facts can always inner join and every foreign key
    resolves by construction.

    LAPSED IS NOT A GRADE - AND NOT A STATUS EITHER. Lapsing is purely a
    lifecycle EVENT (the Lapse rows of fact_membership_events) and appears
    in NO dimension. Grades are Candidate / Qualified (+ id 0 N/A);
    statuses are Practising / Retired (+ id 0 N/A). Gold maps silver
    'lapse' daily rows to grade N/A + status N/A.
====================================================================*/

if not exists (select 1 from Layercake.silv_ref_membership_grade where id = 0)
begin
    set identity_insert Layercake.silv_ref_membership_grade on;
    insert into Layercake.silv_ref_membership_grade (id, grade_name) values (0, 'N/A');
    set identity_insert Layercake.silv_ref_membership_grade off;
end

insert into Layercake.silv_ref_membership_grade (grade_name)
select v.grade_name
from (values ('Candidate'), ('Qualified')) v(grade_name)
where not exists (select 1 from Layercake.silv_ref_membership_grade g where g.grade_name = v.grade_name);
go

if not exists (select 1 from Layercake.silv_ref_assessment_route where id = 0)
begin
    set identity_insert Layercake.silv_ref_assessment_route on;
    insert into Layercake.silv_ref_assessment_route (id, route_code, route_name) values (0, 0, 'N/A');
    set identity_insert Layercake.silv_ref_assessment_route off;
end
go

if not exists (select 1 from Layercake.silv_ref_rpq_variant where id = 0)
begin
    set identity_insert Layercake.silv_ref_rpq_variant on;
    insert into Layercake.silv_ref_rpq_variant (id, variant_id, variant_name)
    values (0, '00000000-0000-0000-0000-000000000000', 'N/A');
    set identity_insert Layercake.silv_ref_rpq_variant off;
end
go

if not exists (select 1 from Layercake.silv_ref_country where id = 0)
begin
    set identity_insert Layercake.silv_ref_country on;
    insert into Layercake.silv_ref_country (id, country_id, country_name, region_name, market_reporting_region)
    values (0, '00000000-0000-0000-0000-000000000000', 'N/A', 'N/A', 'N/A');
    set identity_insert Layercake.silv_ref_country off;
end
go

-- static list - CE gender option set codes
if not exists (select 1 from Layercake.silv_ref_gender where id = 0)
begin
    set identity_insert Layercake.silv_ref_gender on;
    insert into Layercake.silv_ref_gender (id, gender_code, gender_name)
    values
    (0, 0,         'Not stated'),
    (1, 1,         'Male'),
    (2, 2,         'Female'),
    (3, 200000002, 'I use another term'),
    (4, 200000001, 'zz_Prefer to Self-Describe'),
    (5, 192350001, 'zz_Unknown'),
    (6, 200000000, 'I prefer not to say');
    set identity_insert Layercake.silv_ref_gender off;
end
go

if not exists (select 1 from Layercake.silv_ref_membership_status where id = 0)
begin
    set identity_insert Layercake.silv_ref_membership_status on;
    insert into Layercake.silv_ref_membership_status (id, status_name)
    values (0, 'N/A'), (1, 'Practising'), (2, 'Retired');
    set identity_insert Layercake.silv_ref_membership_status off;
end
go

-- lapse reason N/A member. Real codes are loaded by usp_load_silver.
if not exists (select 1 from Layercake.silv_ref_lapse_reason where id = 0)
begin
    set identity_insert Layercake.silv_ref_lapse_reason on;
    insert into Layercake.silv_ref_lapse_reason (id, lapse_code, reason_name) values (0, 0, 'Not recorded');
    set identity_insert Layercake.silv_ref_lapse_reason off;
end
go

-- the dim_date 'NA' member. Events that legitimately pre-date the spine
-- start carry date_id 0 and resolve here.
if not exists (select 1 from Layercake.dim_date where id = 0)
begin
    set identity_insert Layercake.dim_date on;
    insert into Layercake.dim_date (id, [date], [campaign_year], [campaign_quarter])
    values (0, '19000101', 0, 'NA');
    set identity_insert Layercake.dim_date off;
end
go
